INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(35011, 'Hebrews 10:6', 'Hebrews', 10, 6, 'په سوځېدونکو نذرانو او د ګناه په نذرانو ته خوشحاله نه وې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_6.mp3', '', 1761754199, 1761754199),
(35012, 'Hebrews 10:7', 'Hebrews', 10, 7, 'بیا ما وویل: «ای خدایه، زه حاضر یم چې ستا رضا پوره کړم، لکه څنګه چې د تورات په کتاب کې زما په هکله لیکل شوي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_7.mp3', '', 1761754199, 1761754199),
(35013, 'Hebrews 10:8', 'Hebrews', 10, 8, 'لکه څنګه چې مسیح مخکې وویل: «تا نه قربانۍ، نه نذرانې، نه سوځېدونکې نذرانې او نه د ګناه نذرانې غوښتلې او نه په هغو باندې خوشحالېدلې» که څه هم هغه د شریعت له مخې وړاندې کېدلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_8.mp3', '', 1761754199, 1761754199),
(35014, 'Hebrews 10:9', 'Hebrews', 10, 9, 'بیا هغه زیاته کړه: «زه راغلم چې ستا رضا پوره کړم.» بیا خدای مخکینۍ قربانۍ باطلې کړلې، ترڅو د هغو په ځای د عیسی قرباني رامنځته کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_9.mp3', '', 1761754199, 1761754199),
(35015, 'Hebrews 10:10', 'Hebrews', 10, 10, 'نو په دې ډول مونږ د خدای په ارادې او د عیسی مسیح د بدن په قربانولو سره یوځل او د تل دپاره د ګناه څخه پاک شولو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_10.mp3', '', 1761754199, 1761754199),
(35016, 'Hebrews 10:11', 'Hebrews', 10, 11, 'هر کاهن هره ورځ د قربانۍ د ځای په مخکې ودریږي او خپل کار کوي او هماغه یو ډول قرباني بیا بیا وړاندې کوي چې دا قربانۍ هېڅکله نه شي کولای چې ګناهونه له منځه یوسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_11.mp3', '', 1761754199, 1761754199),
(35017, 'Hebrews 10:12', 'Hebrews', 10, 12, 'خو کله چې مسیح د تل دپاره د ګناهونو د له منځه وړلو په خاطر یوځل قرباني ورکړه، نو بیا هغه د خدای ښي لاس ته کښېناست', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_12.mp3', '', 1761754199, 1761754199),
(35018, 'Hebrews 10:13', 'Hebrews', 10, 13, 'او د هماغه وخت نه هغه په دې انتظار دی، ترڅو د هغه دښمنان تر پښو لاندې کړای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_13.mp3', '', 1761754199, 1761754199),
(35019, 'Hebrews 10:14', 'Hebrews', 10, 14, 'ځکه چې هغه د هغې یوې قربانۍ په ورکولو سره هغه خلک د تل دپاره کامل کړل چې د ګناه څخه پاک شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_14.mp3', '', 1761754199, 1761754199),
(35020, 'Hebrews 10:15', 'Hebrews', 10, 15, 'مونږ ته روح القدس هم شاهدي راکوي، ځکه چې هغه اول وایي:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_15.mp3', '', 1761754199, 1761754199),
(35021, 'Hebrews 10:16', 'Hebrews', 10, 16, 'دا هغه لوظ دی چې کوم به یې د هغوی سره په هغه ورځ بیا څښتن وایي: د هغوی زړونو کې به واچوم زه خپل شریعت او وبه یې لیکم د هغوی ذهنونو کې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_16.mp3', '', 1761754199, 1761754199),
(35022, 'Hebrews 10:17', 'Hebrews', 10, 17, 'بیا هغه وایي: نور به زه نه یادوم هېڅکله ګناهونه او بد کارونه د هغوی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_17.mp3', '', 1761754199, 1761754199),
(35023, 'Hebrews 10:18', 'Hebrews', 10, 18, 'نو څرنګه چې دا ګناهونه بخښل شوي دي، نور د ګناهونو دپاره د قربانۍ وړاندې کولو اړتیا نشته. راځئ چې د خدای حضور ته ورنژدې شو', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_18.mp3', '', 1761754199, 1761754199),
(35024, 'Hebrews 10:19', 'Hebrews', 10, 19, 'نو ای خویندو او ورونو! مونږ د عیسی مسیح د وینې په وسیله کولای شو په زړورتیا سره ډېر سپېڅلي ځای ته ورننوځو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_19.mp3', '', 1761754199, 1761754199),
(35025, 'Hebrews 10:20', 'Hebrews', 10, 20, 'هغه مونږ ته یوه نوې او د ژوندون لاره د پردې له منځ نه چې د هغه بدن دی، خلاصه کړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_20.mp3', '', 1761754199, 1761754199),
(35026, 'Hebrews 10:21', 'Hebrews', 10, 21, 'څرنګه چې مونږ یو لوی کاهن لرو چې د خدای د کور مسوولیت یې په غاړه دی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_21.mp3', '', 1761754199, 1761754199),
(35027, 'Hebrews 10:22', 'Hebrews', 10, 22, 'نو راځئ چې د زړه د اخلاصه او په پوره باور سره د خدای حضور ته ورنژدې شو، ځکه چې زمونږ په ګناهکارو وجدانونو باندې د مسیح وینه شیندل شوې ده، ترڅو مونږ پاک کړي او زمونږ بدنونه یې په پاکو اوبو وینځلي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_22.mp3', '', 1761754199, 1761754199),
(35028, 'Hebrews 10:23', 'Hebrews', 10, 23, 'راځئ چې هغه هیله چې مونږ پرې اقرار کوو ټینګه وساتو، ځکه چا چې زمونږ سره وعده کړې ده، هغه وفادار دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_23.mp3', '', 1761754199, 1761754199),
(35029, 'Hebrews 10:24', 'Hebrews', 10, 24, 'راځئ فکر وکړو چې څنګه یو بل مینې او نېکو کارونو ته وهڅوو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_24.mp3', '', 1761754199, 1761754199),
(35030, 'Hebrews 10:25', 'Hebrews', 10, 25, 'مونږ باید د ایماندارانو په غونډو کې یو د بل سره په راټولېدلو کې بې‌پروایي ونه کړو، لکه څنګه چې ځینې خلک داسې عادت لري، بلکې یو بل وهڅوو، په ځانګړې توګه اوس چې مونږ وینو چې د خدای ورځ رانژدې کېدونکې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_25.mp3', '', 1761754199, 1761754199),
(35031, 'Hebrews 10:26', 'Hebrews', 10, 26, 'ځکه که چېرې مونږ په حقیقت باندې په پوهېدلو سره بیاهم په قصدي توګه ګناهونه کوو، نو بیا هېڅ ډول قرباني نه شي کولای زمونږ ګناهونه لېرې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_26.mp3', '', 1761754199, 1761754199),
(35032, 'Hebrews 10:27', 'Hebrews', 10, 27, 'خو یوازې د قضاوت د ورځې وېروونکی انتظار او غضبناکه اور پاتې دی چې د خدای دښمنان به سوځوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_27.mp3', '', 1761754199, 1761754199),
(35033, 'Hebrews 10:28', 'Hebrews', 10, 28, 'هرچا چې به د موسی شریعت نه منلو، هغه به په بې‌رحمۍ سره د دوه یا درې شاهدانو په شاهدۍ ورکولو سره وژل کېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_28.mp3', '', 1761754199, 1761754199),
(35034, 'Hebrews 10:29', 'Hebrews', 10, 29, 'نو بیا فکر وکړئ چې څومره سخته سزا به ورکړل شي هغه چاته چې د خدای زوی تر پښو لاندې کوي او د لوظ د وینې چې هغه یې پاک کړی دی، بې‌عزتي کوي او د فضل د روح سپکاوی کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_29.mp3', '', 1761754199, 1761754199),
(35035, 'Hebrews 10:30', 'Hebrews', 10, 30, 'ځکه مونږ پوهېږو چې خدای وویل: بدل اخیستل زما کار دی، زه به بدل اخلم. او همدارنګه هغه وویل: څښتن به د خپلو خلکو په هکله قضاوت کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_30.mp3', '', 1761754199, 1761754199),
(35036, 'Hebrews 10:31', 'Hebrews', 10, 31, 'د ژوندي خدای په لاسونو کې غورځېدل ډېر هیبتناکه دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_31.mp3', '', 1761754199, 1761754199),
(35037, 'Hebrews 10:32', 'Hebrews', 10, 32, 'خو هغه تېر وختونه در په یاد کړئ چې د خدای نور درباندې وځلېده، نو په هغو ورځو کې تاسو سخت کړاوونه وزغمل او ټینګ پاتې شوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_32.mp3', '', 1761754199, 1761754199),
(35038, 'Hebrews 10:33', 'Hebrews', 10, 33, 'تاسو به کله کله د خلکو په مخکې بې‌عزته کېدلئ او ځورېدلئ، او کله به د نورو سره په دې شیانو کې شریکېدلئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_33.mp3', '', 1761754199, 1761754199),
(35039, 'Hebrews 10:34', 'Hebrews', 10, 34, 'تاسو د بندیانو سره چې په زندان کې وو، خواخوږي لرله او کله به چې ستاسو مال او دولت ستاسو نه په زور اخیستل کېده، نو په خوشحالۍ سره به مو منل، ځکه چې تاسو پوهېدلئ چې تاسو سره له دې نه ډېر ښه او تلپاتې مال او دولت شته.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_34.mp3', '', 1761754199, 1761754199),
(35040, 'Hebrews 10:35', 'Hebrews', 10, 35, 'نو خپله زړورتیا له لاسه مه ورکوئ، ځکه که چېرې تاسو همداسې باور ولرئ، نو لوی اجر به تر‌لاسه کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_35.mp3', '', 1761754199, 1761754199),
(35041, 'Hebrews 10:36', 'Hebrews', 10, 36, 'تاسو ته د صبر او زغم اړتیا ده، ترڅو د خدای اراده پوره کړئ، نو بیا به هغه څه تر‌لاسه کړئ چې هغه یې وعده کړې ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_36.mp3', '', 1761754199, 1761754199),
(35042, 'Hebrews 10:37', 'Hebrews', 10, 37, 'ځکه لکه څنګه چې د خدای کلام وایي: پاتې دی ډېر لږ وخت او هغه څوک چې باید راشي هغه به راشي او وبه نه کړي ځنډ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_37.mp3', '', 1761754199, 1761754199),
(35043, 'Hebrews 10:38', 'Hebrews', 10, 38, 'د ایمان په وسیله به کوي ژوند زما نېکان او څوک چې مخ واړوي ما نه نو زه به نه یمه خوشحاله د هغه نه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_38.mp3', '', 1761754199, 1761754199),
(35044, 'Hebrews 10:39', 'Hebrews', 10, 39, 'خو مونږ هغه خلک نه یو چې د خدای څخه مخ اړوي او تباه کیږي، بلکې مونږ ایمان لرو او ژغورل کېږو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews10_verse_39.mp3', '', 1761754199, 1761754199),
(35045, 'Matthew 7:1', 'Matthew', 7, 1, 'د نورو په هکله قضاوت مه کوئ، ترڅو تاسو تر قضاوت لاندې ونه نیول شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_1.mp3', '', 1761754199, 1761754199),
(35046, 'Matthew 7:2', 'Matthew', 7, 2, 'ځکه لکه څنګه چې تاسو نور خلک ملامتوئ، نو تاسو به هم ملامته کړای شئ. په هره پیمانه چې تاسو یې ورکوئ، نو په هماغه پیمانه به تاسو ته هم درکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_2.mp3', '', 1761754199, 1761754199),
(35047, 'Matthew 7:3', 'Matthew', 7, 3, 'ته ولې د خپل ورور په سترګه کې خسڼی ګورې، خو په خپله سترګه کې غټ لرګی لیدلی نه شې؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_3.mp3', '', 1761754199, 1761754199),
(35048, 'Matthew 7:4', 'Matthew', 7, 4, 'یا ته څنګه خپل ورور ته ویلی شې چې اجازه راکړه ستا د سترګې نه خسڼی راوباسم، حال دا چې ستا په خپله سترګه کې لرګی دی؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_4.mp3', '', 1761754199, 1761754199),
(35049, 'Matthew 7:5', 'Matthew', 7, 5, 'ای منافقه، لومړی د خپلې سترګې نه لرګی وباسه، نو بیا به ستا سترګې هم وغړیږي چې د خپل ورور د سترګې نه خسڼی وباسې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_5.mp3', '', 1761754199, 1761754199),
(35050, 'Matthew 7:6', 'Matthew', 7, 6, 'سپيانو ته سپېڅلي شیان مه ورکوئ او خپلې مرغلرې خوګانو ته مه وراچوئ، هسې نه چې هغه تر‌پښو لاندې کړي او بېرته راوګرځي او په تاسو باندې حمله وکړي. وغواړئ، ولټوئ او وټکوئ (لوقا ۱۱‏:‌۹‌‏-‌۱۳)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_6.mp3', '', 1761754199, 1761754199),
(35051, 'Matthew 7:7', 'Matthew', 7, 7, 'وغواړئ، نو تاسو ته به درکړل شي. ولټوئ نو پیدا به یې کړئ. وټکوئ نو دروازه به درته خلاصه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_7.mp3', '', 1761754199, 1761754199),
(35052, 'Matthew 7:8', 'Matthew', 7, 8, 'ځکه هرڅوک چې څه وغواړي، نو لاسته به یې راوړي او څوک یې چې ولټوي، نو پیدا به یې کړي او څوک چې دروازه وټکوي، نو ورته خلاصه به شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_8.mp3', '', 1761754199, 1761754199),
(35053, 'Matthew 7:9', 'Matthew', 7, 9, 'ایا په تاسو کې داسې څوک شته چې زوی یې ورڅخه ډوډۍ وغواړي او هغه ورته تیږه ورکړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_9.mp3', '', 1761754199, 1761754199),
(35054, 'Matthew 7:10', 'Matthew', 7, 10, 'او یا ورڅخه ماهي وغواړي او هغه ورته مار ورکړي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_10.mp3', '', 1761754199, 1761754199),
(35055, 'Matthew 7:11', 'Matthew', 7, 11, 'نو تاسو چې بد خلک یئ، په دې پوهېږئ چې خپلو اولادونو ته څنګه ښه شیان ورکړئ، نو ستاسو اسماني پلار به څومره ښه شیان هغو خلکو ته ورکړي چې ورڅخه ویې غواړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_11.mp3', '', 1761754199, 1761754199),
(35056, 'Matthew 7:12', 'Matthew', 7, 12, 'د نورو سره داسې چلند کوئ لکه څنګه چې تاسو یې د ځان دپاره د هغوی څخه غواړئ. دا هغه څه دي چې تورات او د پیغمبرانو لیکنې یې وایي. تنګه دروازه (لوقا ۱۳‏:‌۲۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_12.mp3', '', 1761754199, 1761754199),
(35057, 'Matthew 7:13', 'Matthew', 7, 13, 'په تنګه دروازه ننوځئ، ځکه کومه دروازه چې لویه ده او هغه لاره چې اسانه ده هغه د تباهۍ خواته ځي او کوم خلک چې په دې لاره ځي هغه زیات دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_13.mp3', '', 1761754199, 1761754199),
(35058, 'Matthew 7:14', 'Matthew', 7, 14, 'خو کومه دروازه چې د تلپاتې ژوندون خواته ځي هغه تنګه او لاره یې سخته ده او د هغې موندونکي هم لږ دي. ونه او د هغې مېوه (لوقا ۶‏:‌۴۳‌‏-‌۴۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_14.mp3', '', 1761754199, 1761754199),
(35059, 'Matthew 7:15', 'Matthew', 7, 15, 'د جعلي پیغمبرانو سره احتیاط کوئ، هغوی د پسونو په شکل کې تاسو ته راځي، خو په حقیقت کې داړونکي لېوان دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_15.mp3', '', 1761754199, 1761754199),
(35060, 'Matthew 7:16', 'Matthew', 7, 16, 'تاسو به هغوی د خپلو عملونو څخه وپېژنئ. ایا د اغزو څخه څوک انګور یا انځر راټولولی شي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_16.mp3', '', 1761754199, 1761754199),
(35061, 'Matthew 7:17', 'Matthew', 7, 17, 'نو هره ښه ونه ښه مېوه نیسي او خرابه ونه خرابه مېوه نیسي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_17.mp3', '', 1761754199, 1761754199),
(35062, 'Matthew 7:18', 'Matthew', 7, 18, 'ښه ونه خرابه مېوه نه شي نیولی او نه خرابه ونه ښه مېوه نیولی شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_18.mp3', '', 1761754199, 1761754199),
(35063, 'Matthew 7:19', 'Matthew', 7, 19, 'کومه ونه چې ښه مېوه نه نیسي، نو هغه ونه به ووهل شي او په اور کې به واچول شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_19.mp3', '', 1761754199, 1761754199),
(35064, 'Matthew 7:20', 'Matthew', 7, 20, 'په دې ډول به تاسو هغوی د خپلو عملونو څخه وپېژنئ. زه تاسو هېڅ نه پېژنم (لوقا ۱۳‏:‌۲۵‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_20.mp3', '', 1761754199, 1761754199),
(35065, 'Matthew 7:21', 'Matthew', 7, 21, 'هر هغه څوک چې ماته باداره، باداره ووایي د خدای په پاچاهۍ کې به وردننه نه شي، خو یوازې هغه خلک به دننه شي چې زما د اسماني پلار اراده پوره کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_21.mp3', '', 1761754199, 1761754199),
(35066, 'Matthew 7:22', 'Matthew', 7, 22, 'د اخرت په ورځ به ډېر ماته وایي: ‹ای باداره، ای باداره، ایا ستا په نوم مونږ د خدای پیغام ونه رساوه؟ ایا ستا په نوم مو پېریان نه وو ویستلي؟ ایا ستا په نوم مو ډېرې معجزې ونه ښودلې؟›', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_22.mp3', '', 1761754199, 1761754199),
(35067, 'Matthew 7:23', 'Matthew', 7, 23, 'بیا به زه هغوی ته په ښکاره ووایم: ‹ای بدکارانو، زه تاسو هېڅ نه پېژنم، زما د مخې نه لېرې شئ.› دوه ډوله بنیادونه (لوقا ۶‏:‌۴۷‌‏-‌۴۹)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_23.mp3', '', 1761754199, 1761754199),
(35068, 'Matthew 7:24', 'Matthew', 7, 24, 'نو هرڅوک چې زما دا خبرې اوري او عمل ورباندې کوي هغه د هغه پوه سړي په شان دی چې خپل کور یې په تیږو باندې جوړ کړی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_24.mp3', '', 1761754199, 1761754199),
(35069, 'Matthew 7:25', 'Matthew', 7, 25, 'چې باران وشو او سېلاب راغی او سخت توفان په هغه کور باندې راغی، خو هغه راونه غورځېده، ځکه چې بنیاد یې په تیږو باندې ایښودل شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_25.mp3', '', 1761754199, 1761754199),
(35070, 'Matthew 7:26', 'Matthew', 7, 26, 'خو هرڅوک چې زما خبرې واوري او عمل ورباندې ونه کړي، نو هغه د هغه ناپوه سړي په شان دی چې خپل کور یې په شګو باندې جوړ کړی ؤ،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_26.mp3', '', 1761754199, 1761754199),
(35071, 'Matthew 7:27', 'Matthew', 7, 27, 'او کله چې باران وشو او سېلاب راغی او سخت توفان په هغه کور باندې راغی، نو هغه راوغورځېد او بیخي وران شو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_27.mp3', '', 1761754199, 1761754199),
(35072, 'Matthew 7:28', 'Matthew', 7, 28, 'کله چې عیسی دا خبرې پای ته ورسولې، نو خلک د هغه تعلیم ته حیران پاتې شول،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_28.mp3', '', 1761754199, 1761754199),
(35073, 'Matthew 7:29', 'Matthew', 7, 29, 'ځکه چې هغه د شریعت د عالمانو په شان نه بلکې په واک او اختیار سره هغوی ته تعلیم ورکاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/matthew7_verse_29.mp3', '', 1761754199, 1761754199),
(35074, 'Hebrews 7:1', 'Hebrews', 7, 1, 'ملک‌صدق د سالیم پاچا او د خدای تعالی کاهن ؤ. کله چې ابراهیم پاچاهانو ته د ماتې ورکولو نه وروسته بېرته راغی، نو ملک‌صدق د هغه سره مخامخ شو او هغه ته یې برکت ورکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_1.mp3', '', 1761754199, 1761754199),
(35075, 'Hebrews 7:2', 'Hebrews', 7, 2, 'او هرڅه چې ابراهیم په جنګ کې تر‌لاسه کړي وو، د هغو لسمه برخه یې ملک‌صدق ته ورکړه. د ملک‌صدق د نوم لومړنی معنی «صادق پاچا» او بیا د سالیم پاچا یعنې «د سولې او سلامتۍ پاچا» دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_2.mp3', '', 1761754199, 1761754199),
(35076, 'Hebrews 7:3', 'Hebrews', 7, 3, 'هغه بې‌پلاره، بې‌موره او بې‌شجرې دی. د هغه د ژوند پیل او پای نه دی معلوم. خو هغه د خدای د زوی په شان تل ترتله کاهن دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_3.mp3', '', 1761754199, 1761754199),
(35077, 'Hebrews 7:4', 'Hebrews', 7, 4, 'ګورئ چې ملک‌صدق څومره لوی انسان ؤ، تر دې چې زمونږ نیکه ابراهیم ورته د خپل غنیمت لسمه برخه ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_4.mp3', '', 1761754199, 1761754199),
(35078, 'Hebrews 7:5', 'Hebrews', 7, 5, 'شریعت د لاوي اولادې ته چې د کاهنۍ مقام ته رسیږي، حکم کوي چې د اسراییلو د خلکو یعنې خپل قوم څخه لسمه برخه راټوله کړي، که څه هم هغوی د ابراهیم اولاده ده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_5.mp3', '', 1761754199, 1761754199),
(35079, 'Hebrews 7:6', 'Hebrews', 7, 6, 'سره له دې چې ملک‌صدق د لاوي د اولادې څخه نه دی، خو هغه د ابراهیم نه لسمه برخه واخیستله او ابراهیم ته یې چې خدای ورسره وعده کړې وه، برکت ورکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_6.mp3', '', 1761754199, 1761754199),
(35080, 'Hebrews 7:7', 'Hebrews', 7, 7, 'په دې کې شک نشته چې برکت ورکوونکی د برکت اخیستونکي نه ډېر لوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_7.mp3', '', 1761754199, 1761754199),
(35081, 'Hebrews 7:8', 'Hebrews', 7, 8, 'له یوې خوا هغه کاهنان چې لسمه برخه راټولوي، فاني انسانان دي او له بلې خوا ملک‌صدق چې لسمه برخه یې واخیستله، ژوندی دی لکه څنګه چې د خدای په کلام کې ویل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_8.mp3', '', 1761754199, 1761754199),
(35082, 'Hebrews 7:9', 'Hebrews', 7, 9, 'نو ویلی شو چې کله ابراهیم لسمه برخه ورکوله، لاویانو هم چې د لسمې برخې اخیستونکي وو، د ابراهیم په وسیله ملک‌صدق ته لسمه برخه ورکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_9.mp3', '', 1761754199, 1761754199),
(35083, 'Hebrews 7:10', 'Hebrews', 7, 10, 'ځکه کله چې ملک‌صدق د ابراهیم سره ولیدل، نو لاوي لا د ابراهیم په کورنۍ کې نه ؤ پیدا شوی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_10.mp3', '', 1761754199, 1761754199),
(35084, 'Hebrews 7:11', 'Hebrews', 7, 11, 'دا د لاویانو د کاهنتوب په وسیله ؤ چې د اسراییلو خلکو ته شریعت ورکړل شوی ؤ. نو که چېرې د لاوي کاهنانو کار پوره شوی وای، نو بیا د بل کاهن راتللو ته څه اړتیا وه چې د ملک‌صدق په شان وي، نه د هارون په شان.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_11.mp3', '', 1761754199, 1761754199),
(35085, 'Hebrews 7:12', 'Hebrews', 7, 12, 'ځکه کله چې په کاهنتوب کې بدلون رامنځته شي، نو په شریعت کې هم باید بدلون رامنځته شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_12.mp3', '', 1761754199, 1761754199),
(35086, 'Hebrews 7:13', 'Hebrews', 7, 13, 'نو د چا په هکله چې دا خبرې شوې دي هغه د بلې قبیلې څخه ؤ او د هغې قبیلې څخه هېچا هم د قربانۍ د ځای خدمت نه ؤ کړی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_13.mp3', '', 1761754199, 1761754199),
(35087, 'Hebrews 7:14', 'Hebrews', 7, 14, 'ځکه دا ښکاره ده چې زمونږ څښتن د یهودا د قبیلې څخه دی. سره له دې چې موسی هېڅکله د کاهنتوب په هکله د هغوی سره خبرې نه دي کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_14.mp3', '', 1761754199, 1761754199),
(35088, 'Hebrews 7:15', 'Hebrews', 7, 15, 'دا موضوع به نوره هم ښه روښانه شي کله چې د ملک‌صدق په شان کوم بل کاهن راپیدا شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_15.mp3', '', 1761754199, 1761754199),
(35089, 'Hebrews 7:16', 'Hebrews', 7, 16, 'هغه کاهن شو، خو د هغو قوانینو له مخې نه چې هغه به د لاوي کورنۍ کې پیدا شي، بلکې د هغه ژوند د قدرت په وسیله چې هېڅکله نه ختمیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_16.mp3', '', 1761754199, 1761754199),
(35090, 'Hebrews 7:17', 'Hebrews', 7, 17, 'ځکه چې د خدای کلام د هغه په هکله داسې شاهدي ورکوي: «ته به کاهن یې تر ابده د ملک‌صدق په شان»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_17.mp3', '', 1761754199, 1761754199),
(35091, 'Hebrews 7:18', 'Hebrews', 7, 18, 'نو پخواني حکمونه باطل شول، ځکه چې هغه کمزوري او بې‌اثره وو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_18.mp3', '', 1761754199, 1761754199),
(35092, 'Hebrews 7:19', 'Hebrews', 7, 19, 'ځکه چې شریعت هېڅ شی کامل نه کړ. خو اوس له مخکې نه یوه ښه هیله پیدا شوه چې د هغې په وسیله مونږ خدای ته نژدې کېدای شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_19.mp3', '', 1761754199, 1761754199),
(35093, 'Hebrews 7:20', 'Hebrews', 7, 20, 'دا نوی کاهنتوب د قسم په خوړلو سره پیل شو، خو نور بې له کوم قسم نه کاهنان شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_20.mp3', '', 1761754199, 1761754199),
(35094, 'Hebrews 7:21', 'Hebrews', 7, 21, 'خو عیسی په قسم خوړلو سره کاهن شو، کله چې خدای هغه ته وویل: څښتن قسم خوړلی مات به نه شي هېڅ وخت چې تر ابده به ته یې کاهن', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_21.mp3', '', 1761754199, 1761754199),
(35095, 'Hebrews 7:22', 'Hebrews', 7, 22, 'د همدې قسم له امله عیسی د خدای سره له مخکې نه د یو ښه لوظ ضامن شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_22.mp3', '', 1761754199, 1761754199),
(35096, 'Hebrews 7:23', 'Hebrews', 7, 23, 'په پخوا زمانه کې زیات شمېر کاهنان راغلل، ځکه چې مرګ هغوی نه پرېښودل چې خپل خدمت ته دوام ورکړي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_23.mp3', '', 1761754199, 1761754199),
(35097, 'Hebrews 7:24', 'Hebrews', 7, 24, 'خو د عیسی کاهنتوب د تل دپاره دی، ځکه چې هغه تل ترتله ژوندی دی،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_24.mp3', '', 1761754199, 1761754199),
(35098, 'Hebrews 7:25', 'Hebrews', 7, 25, 'نو له دې امله عیسی کولای شي هغو خلکو ته چې د هغه په وسیله خدای ته نژدې شي، په پوره توګه خلاصون ورکړي، ځکه چې هغه تل ترتله ژوندی دی او د هغوی شفاعت کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_25.mp3', '', 1761754199, 1761754199),
(35099, 'Hebrews 7:26', 'Hebrews', 7, 26, 'نو مونږ داسې لوی کاهن ته اړتیا لرو چې هغه سپېڅلی، بې‌ګناه، بې‌عیبه، د ګناهکارانو نه بېل او د اسمانونو نه اوچت وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_26.mp3', '', 1761754199, 1761754199),
(35100, 'Hebrews 7:27', 'Hebrews', 7, 27, 'هغه دې ته اړتیا نه لري چې د نورو لویو کاهنانو په شان هره ورځ اول د خپلو ګناهونو دپاره او بیا د خلکو د ګناهونو دپاره قرباني ورکړي، ځکه چې هغه خپل ځان یوځل او د تل دپاره قرباني کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_27.mp3', '', 1761754199, 1761754199),
(35101, 'Hebrews 7:28', 'Hebrews', 7, 28, 'شریعت داسې خلک د لویو کاهنانو په توګه ټاکي چې په روحاني توګه کمزوري وي، خو د شریعت نه وروسته خدای د قسم په خوړلو سره خپل زوی کاهن وټاکه چې د تل دپاره کامل کړی شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/hebrews7_verse_28.mp3', '', 1761754199, 1761754199),
(35102, 'Acts 18:1', 'Acts', 18, 1, 'له هغې وروسته پولوس له آتن څخه روان شو او قرنتوس ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_1.mp3', '', 1761754199, 1761754199),
(35103, 'Acts 18:2', 'Acts', 18, 2, 'په هغه ځای کې هغه د یو یهودي سره چې اکیلا نومېده او په اصل کې د پونتوس څخه ؤ، مخامخ شو. اکیلا د خپلې ښځې پریسکیلا سره نوی له ایټالیې څخه راغلی ؤ، ځکه چې کلودیوس امپراتور امر کړی ؤ چې ټول یهودیان دې له روم څخه ووځي. پولوس لاړ چې د هغوی سره وګوري', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_2.mp3', '', 1761754199, 1761754199),
(35104, 'Acts 18:3', 'Acts', 18, 3, 'او په دې خاطر چې هغه هم د هغوی په شان خېمه جوړوونکی ؤ، نو د هغوی سره پاتې شو او یوځای یې ورسره کار کاوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_3.mp3', '', 1761754199, 1761754199),
(35105, 'Acts 18:4', 'Acts', 18, 4, 'د هر سبت په ورځ هغه په کنیسه کې بحث کاوه او کوښښ یې کاوه چې یهودیانو او یونانیانو ته قناعت ورکړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_4.mp3', '', 1761754199, 1761754199),
(35106, 'Acts 18:5', 'Acts', 18, 5, 'کله چې سیلاس او تیموتاوس د مقدونیې څخه راغلل، نو پولوس خپل ټول وخت د کلام په بیانولو تېر کړ. هغه یهودیانو ته دا شاهدي ورکوله چې عیسی هماغه مسیح دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_5.mp3', '', 1761754199, 1761754199),
(35107, 'Acts 18:6', 'Acts', 18, 6, 'خو کله چې یهودیانو د هغه سره مخالفت وکړ او هغه ته یې بد رد وویل، نو پولوس خپل کالي وڅنډل او هغوی ته یې وویل: «ستاسو خون ستاسو په خپله غاړه دی. زه یې د مسوولیت څخه خلاص یم. زه به له دې وروسته غیریهودیانو ته ورځم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_6.mp3', '', 1761754199, 1761754199),
(35108, 'Acts 18:7', 'Acts', 18, 7, 'نو پولوس له هغه ځای څخه لاړ او د تیتیوس یوستوس په نوم د یو غیریهودي کور ته چې د خدای عبادت به یې کاوه، لاړ. د هغه کور د کنیسې په څنګ کې ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_7.mp3', '', 1761754199, 1761754199),
(35109, 'Acts 18:8', 'Acts', 18, 8, 'کرسپوس چې د کنیسې مشر ؤ، د خپلې ټولې کورنۍ سره په څښتن عیسی باندې ایمان راوړ. همدارنګه د قرنتوس ډېرو خلکو چې د پولوس پیغام یې اورېده، نو ایمان یې راوړ او د تعمید غسل ورته ورکړل شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_8.mp3', '', 1761754199, 1761754199),
(35110, 'Acts 18:9', 'Acts', 18, 9, 'یوه شپه څښتن په رویا کې د پولوس سره خبرې وکړې او ورته ویې ویل: «مه وېرېږه، بلکې خپل وعظ کوه او غلی مه پاتې کېږه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts18_verse_9.mp3', '', 1761754199, 1761754199);